import{_ as e,o as d,c as l,ah as r}from"./chunks/framework.DjU4PSOm.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"tags":["computer/project"],"date":"2026-11-21T00:00:00.000Z"},"headers":[{"level":3,"title":"오늘 한 것 (2026-11-18 ~ 11-21)","slug":"오늘-한-것-2026-11-18-11-21","link":"#오늘-한-것-2026-11-18-11-21","children":[]},{"level":3,"title":"1. 비슷한 앱에서 가져온 것","slug":"_1-비슷한-앱에서-가져온-것","link":"#_1-비슷한-앱에서-가져온-것","children":[]},{"level":3,"title":"2. 신고·차단","slug":"_2-신고·차단","link":"#_2-신고·차단","children":[]},{"level":3,"title":"3. 출시 점검에서 찾은 보안 구멍","slug":"_3-출시-점검에서-찾은-보안-구멍","link":"#_3-출시-점검에서-찾은-보안-구멍","children":[]},{"level":3,"title":"4. 출시 요건 1~7단계","slug":"_4-출시-요건-1-7단계","link":"#_4-출시-요건-1-7단계","children":[]},{"level":3,"title":"5. 단계별 소통 완성","slug":"_5-단계별-소통-완성","link":"#_5-단계별-소통-완성","children":[]},{"level":3,"title":"6. 푸시 알림","slug":"_6-푸시-알림","link":"#_6-푸시-알림","children":[]},{"level":3,"title":"7. Heyring과 비교","slug":"_7-heyring과-비교","link":"#_7-heyring과-비교","children":[]},{"level":3,"title":"8. 이번에 배운 것","slug":"_8-이번에-배운-것","link":"#_8-이번에-배운-것","children":[]},{"level":3,"title":"9. 남은 과제","slug":"_9-남은-과제","link":"#_9-남은-과제","children":[]}],"relativePath":"computer/project/Zing/13. 익명성·안전·출시 준비, 단계 기능과 푸시 알림 (2026-11-21).md","filePath":"computer/project/Zing/13. 익명성·안전·출시 준비, 단계 기능과 푸시 알림 (2026-11-21).md"}'),o={name:"computer/project/Zing/13. 익명성·안전·출시 준비, 단계 기능과 푸시 알림 (2026-11-21).md"};function i(a,t,n,s,c,h){return d(),l("div",null,[...t[0]||(t[0]=[r(`<h3 id="오늘-한-것-2026-11-18-11-21" tabindex="-1">오늘 한 것 (2026-11-18 ~ 11-21) <a class="header-anchor" href="#오늘-한-것-2026-11-18-11-21" aria-label="Permalink to &quot;오늘 한 것 (2026-11-18 ~ 11-21)&quot;">​</a></h3><p>번역 이후 남은 것들을 한꺼번에 채웠다. 비슷한 앱(모씨, 어라운드)을 보고 <strong>가벼운 진입과 익명성</strong>을 보강했고, 스토어에 올릴 수 있는 수준인지 보안 위주로 점검했다. 그다음 테스터를 받을 수 있게 2~4단계 소통과 푸시 알림까지 만들었다.</p><table tabindex="0"><thead><tr><th>순서</th><th>작업</th><th>상태</th></tr></thead><tbody><tr><td>1</td><td>익명성: 매칭 전 닉네임 숨김, 국적 공개 선택, 지역 선택</td><td>완료</td></tr><tr><td>2</td><td>신고·차단 + 운영자 신고 처리</td><td>완료</td></tr><tr><td>3</td><td>먼저 주고 받기: 반응 3개 남겨야 징</td><td>완료</td></tr><tr><td>4</td><td>출시 점검: 보안 구멍 4개 수정, 출시 요건 1~7단계</td><td>완료</td></tr><tr><td>5</td><td>4단계 채팅 (번역 포함)</td><td>완료</td></tr><tr><td>6</td><td>2단계 오늘의 질문, 3단계 서로 질문</td><td>완료</td></tr><tr><td>7</td><td>푸시 알림, 자동 검사(CI)</td><td>코드·DB 완료, 폰 확인은 앱 빌드 후</td></tr></tbody></table><hr><h3 id="_1-비슷한-앱에서-가져온-것" tabindex="-1">1. 비슷한 앱에서 가져온 것 <a class="header-anchor" href="#_1-비슷한-앱에서-가져온-것" aria-label="Permalink to &quot;1. 비슷한 앱에서 가져온 것&quot;">​</a></h3><table tabindex="0"><thead><tr><th>앱</th><th>본 것</th><th>Zing에 적용</th></tr></thead><tbody><tr><td>모씨</td><td>익명으로 글을 올리고 공감을 주고받음</td><td>매칭 전에는 닉네임 대신 &quot;일본 교환학생&quot;처럼 표시</td></tr><tr><td>어라운드</td><td>글을 읽으려면 먼저 공감을 남기는 구조</td><td>새 징을 보내려면 오늘 다른 일기 3개에 반응</td></tr><tr><td>둘 다</td><td>가입이 가벼움</td><td>가입 2단계, 국적·지역은 선택</td></tr></tbody></table><ul><li><strong>가입 필수</strong>: 닉네임(직접 지음), 학생 구분, 읽을 언어. <strong>선택</strong>: 국적(공개/비공개), 지역. 성별 항목은 없앴다.</li><li>국적을 비공개로 하면 &quot;교환학생&quot;으로만 보인다. 비공개 국적은 DB 함수가 <code>null</code>로 바꿔서 내보내므로 API를 직접 불러도 안 보인다.</li><li>반응 3개 조건은 <strong>받은 징 수락에는 적용하지 않았다.</strong> 상대가 이미 관심을 보낸 경우라 막을 이유가 없다.</li></ul><h3 id="_2-신고·차단" tabindex="-1">2. 신고·차단 <a class="header-anchor" href="#_2-신고·차단" aria-label="Permalink to &quot;2. 신고·차단&quot;">​</a></h3><ul><li><strong>차단</strong>: 방향과 상관없이 서로 안 보이게 한다. 피드에서 제외, 징·반응 불가, 진행 중이던 매칭은 끝낸다(기록은 남김).</li><li><strong>신고</strong>: 사유를 고르면 자동으로 차단까지 된다. 서로 다른 3명이 신고한 일기는 운영자 확인 전에도 피드에서 숨긴다.</li><li>피드 카드, 받은 징, 교환일기 화면 위쪽 세 군데에 신고 버튼이 있다.</li><li><strong>운영자 처리</strong>는 Supabase SQL Editor에서만 한다. <code>admin_report_queue</code>로 보고 <code>admin_hide_diary</code>, <code>admin_suspend_user</code>, <code>admin_resolve_reports</code>로 처리한다. 앱에서 부르면 401이다. Apple은 신고를 24시간 안에 처리하라고 요구한다.</li></ul><h3 id="_3-출시-점검에서-찾은-보안-구멍" tabindex="-1">3. 출시 점검에서 찾은 보안 구멍 <a class="header-anchor" href="#_3-출시-점검에서-찾은-보안-구멍" aria-label="Permalink to &quot;3. 출시 점검에서 찾은 보안 구멍&quot;">​</a></h3><table tabindex="0"><thead><tr><th>구멍</th><th>왜 위험한가</th><th>막은 방법</th></tr></thead><tbody><tr><td><code>zings</code> 테이블을 직접 읽을 수 있었음</td><td>보낸 사람이 거절·차단 여부를 알 수 있음</td><td>직접 조회 차단, 함수로만</td></tr><tr><td>일기 수정으로 작성 날짜를 바꿀 수 있었음</td><td>단계 해금 조작</td><td>트리거로 작성일·작성자 고정</td></tr><tr><td>일기 글자 수를 앱에서만 검사</td><td>1글자 일기, 글자 수 위조</td><td>DB 트리거로 200~600자 강제, 글자 수는 DB가 계산</td></tr><tr><td><code>diaries</code>에 사용자 FK가 없음</td><td>탈퇴해도 일기가 남음</td><td>FK + on delete cascade</td></tr></tbody></table><h3 id="_4-출시-요건-1-7단계" tabindex="-1">4. 출시 요건 1~7단계 <a class="header-anchor" href="#_4-출시-요건-1-7단계" aria-label="Permalink to &quot;4. 출시 요건 1~7단계&quot;">​</a></h3><table tabindex="0"><thead><tr><th>단계</th><th>내용</th></tr></thead><tbody><tr><td>1</td><td>앱 안에서 회원 탈퇴 (Apple·Google 필수). Edge Function <code>delete-account</code></td></tr><tr><td>2</td><td>이용약관·개인정보처리방침 초안, 가입 시 필수 동의 4개(만 14세, 약관, 수집·이용, 국외 이전)</td></tr><tr><td>3</td><td>운영자 신고 처리 수단</td></tr><tr><td>4</td><td>앱 식별자 <code>com.zingdiary.app</code> (개인 이름 없이), <code>eas.json</code></td></tr><tr><td>5</td><td>이메일 6자리 코드 인증, 한국 학생은 <code>.ac.kr</code> 필수. 프로필은 DB 트리거가 만듦</td></tr><tr><td>6</td><td>비밀번호 찾기 (코드 + 새 비밀번호)</td></tr><tr><td>7</td><td>비밀번호 8자 이상, 영문+숫자</td></tr></tbody></table><ul><li>프로필 생성을 앱에서 DB 트리거로 옮긴 이유: 앱이 <code>users</code>에 직접 쓰면 동의 없이, 학교 메일 없이 가입하는 API 호출을 막을 수 없다.</li><li>공개 사이트(<code>site/</code>)를 <code>lib/legal.ts</code>에서 생성한다. 스토어에 넣을 개인정보처리방침 주소와 계정 삭제 안내 주소가 필요하기 때문이다. 도메인을 사면 올린다.</li><li>남은 것은 돈이나 계정이 필요한 일이다: 도메인, 메일 서비스(SMTP), 개발자 계정, Google 비공개 테스트(테스터 12명 × 14일). 정리는 Zing 저장소 <code>docs/release-checklist.md</code>.</li></ul><h3 id="_5-단계별-소통-완성" tabindex="-1">5. 단계별 소통 완성 <a class="header-anchor" href="#_5-단계별-소통-완성" aria-label="Permalink to &quot;5. 단계별 소통 완성&quot;">​</a></h3><table tabindex="0"><thead><tr><th>단계</th><th>기능</th><th>규칙</th></tr></thead><tbody><tr><td>2</td><td>오늘의 질문</td><td>모두 같은 질문(한·영), 5자 답. <strong>내가 답해야 상대 답이 보임</strong></td></tr><tr><td>3</td><td>서로 질문</td><td>7자 질문, 답 길이는 질문자가 5·20·100자 중 선택, 하루 3개</td></tr><tr><td>4</td><td>채팅</td><td>1~1000자, 하루 300개, 메시지 번역(일기와 합쳐 하루 50회)</td></tr></tbody></table><ul><li>질문 30개를 <code>question_bank</code>에 넣고 날짜로 돌려 쓴다.</li><li>&quot;내가 답해야 상대 답이 보임&quot;은 화면이 아니라 DB 함수가 상대 답을 <code>null</code>로 돌려준다.</li><li>채팅은 4초마다 새 메시지를 확인하는 방식이다. 실시간 연결(Realtime)보다 단순하고, 지금 규모에선 충분하다.</li></ul><h3 id="_6-푸시-알림" tabindex="-1">6. 푸시 알림 <a class="header-anchor" href="#_6-푸시-알림" aria-label="Permalink to &quot;6. 푸시 알림&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>징 도착 / 매칭 / 새 메시지 / 새 질문</span></span>
<span class="line"><span>   → DB 트리거 → send_push() → pg_net으로 Expo 푸시 API 호출 → FCM(Android)·APNs(iOS) → 폰</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li><strong>서버를 따로 두지 않았다.</strong> Expo 푸시 API는 인증 없이 토큰만으로 보낼 수 있다. 그래서 DB 트리거가 <code>pg_net</code>(비동기 HTTP)으로 바로 부른다. 비동기라 알림이 실패해도 메시지 저장은 막히지 않는다.</li><li><strong>알림 문구는 익명</strong>이다. 닉네임·일기·메시지 내용을 넣지 않는다. 잠금 화면에 보이기 때문이다.</li><li>같은 사람이 2분 안에 또 보낸 메시지는 알리지 않는다. 채팅에서 알림이 쏟아지는 걸 막는다.</li><li>설정에서 끌 수 있고, 로그아웃하면 그 기기 토큰을 계정에서 떼어낸다.</li><li><strong>Android Expo Go에서는 안 된다.</strong> SDK 53부터 Expo Go에서 원격 푸시가 빠졌다. <code>expo-notifications</code>를 Android Expo Go에서 불러오기만 해도 오류를 내서, 필요할 때만 불러오도록 했다. 실제 확인은 <code>eas init</code> → FCM 키 등록 → <code>eas build</code>로 APK를 만든 뒤에 한다.</li><li>테스트: 가짜 토큰으로 보내 Expo 서버가 <code>DeviceNotRegistered</code>로 응답하는 것까지 확인했다. 연속 메시지 두 개에 요청 1건만 나가는 것도 확인했다.</li></ul><p><strong>테스트하다 헷갈린 것</strong>: 메시지 두 개를 SQL 한 문장(<code>insert ... select ... generate_series(1,2)</code>)으로 넣었더니 알림이 하나도 안 나갔다. 행 단위 AFTER 트리거는 문장이 끝난 뒤에 실행된다. 그래서 두 행이 서로를 &quot;2분 안에 보낸 메시지&quot;로 보고 둘 다 건너뛴 것이다. 실제 앱은 메시지를 하나씩 보내서 문제없다.</p><h3 id="_7-heyring과-비교" tabindex="-1">7. Heyring과 비교 <a class="header-anchor" href="#_7-heyring과-비교" aria-label="Permalink to &quot;7. Heyring과 비교&quot;">​</a></h3><p>AI 전화영어 앱 Heyring은 매일 5분을 무료로 준다. AI 음성은 1분마다 비용이 들어서, 매일 쓰는 무료 사용자 한 명에 월 수천~수만 원이 든다(추정). 그래서 5분 제한이 꼭 필요하고, 그 지점에서 구독을 권한다.</p><p>Zing은 번역을 누를 때만 비용이 들고, 번역은 저장해서 재사용한다. 그래서 핵심 기능을 계속 무료로 줘도 부담이 거의 없다. Zing의 하루 제한(징 2회, 번역 50회)은 비용보다 <strong>분위기와 악용 방지</strong>가 목적이다.</p><p>채용 공고(서버: MySQL·AWS, CI/CD·모니터링 강조)에서 가져온 것:</p><ul><li><strong>CI 추가</strong>: GitHub에 push할 때마다 타입 검사, Expo 설정 검사, 약관 사이트 생성을 자동으로 돌린다.</li><li><strong>오류 모니터링</strong>은 할 일로 남김 (Sentry 무료 플랜, 계정 필요).</li><li>서버 구성은 따라가지 않았다. 실시간 AI 음성 서비스와 일기 앱은 필요한 게 다르다.</li></ul><h3 id="_8-이번에-배운-것" tabindex="-1">8. 이번에 배운 것 <a class="header-anchor" href="#_8-이번에-배운-것" aria-label="Permalink to &quot;8. 이번에 배운 것&quot;">​</a></h3><ul><li><strong>규칙은 DB가 지킨다.</strong> 이번에 찾은 구멍은 전부 &quot;앱에서만 검사&quot;한 곳이었다. 앱은 우회할 수 있다.</li><li><strong>Supabase MCP는 <code>drop</code>이 들어간 마이그레이션을 거절한다.</strong> <code>create or replace</code>, <code>create or replace trigger</code>로 바꿔 쓰면 된다. 함수 안의 <code>delete</code>도 거절돼서 차단은 행을 지우지 않고 <code>matched_at=null</code>로 매칭만 끝내게 했다.</li><li><strong>plpgsql 파라미터 이름이 컬럼 이름과 같으면 모호하다는 오류가 난다.</strong> <code>target_user</code>, <code>question_text</code>처럼 다르게 짓는다.</li><li><strong>보안 점검(advisor)을 마이그레이션마다 돌린다.</strong> 이번에도 새 함수 4개가 로그인 안 한 사용자에게 열려 있던 걸 잡았다.</li></ul><h3 id="_9-남은-과제" tabindex="-1">9. 남은 과제 <a class="header-anchor" href="#_9-남은-과제" aria-label="Permalink to &quot;9. 남은 과제&quot;">​</a></h3><ul><li>폰에서 푸시 확인 (<code>eas init</code>, FCM, 앱 빌드)</li><li>도메인 → 사이트·문의 메일·SMTP 연결 (그 전까지 인증 메일은 팀원 주소로만 감)</li><li>실제 계정 끝까지 테스트: 가입 메일, 탈퇴</li><li>일기 수정·삭제 화면, 사용 언어·닉네임 변경, 차단 목록·해제</li><li>오류 모니터링(Sentry)</li></ul>`,30)])])}const g=e(o,[["render",i]]);export{u as __pageData,g as default};
